{"file_path": "C:\work\toyapp\entry\src\main\ets\pages\Index.ets", "content": "@Entry
@Component
struct Index {
  // AppStorage keeps the tally across page/component recreation while the
  // application process is alive. A cold launch starts from 0, and Reset
  // explicitly clears the count just like MainActivity.
  @StorageLink('count') count: number = 0;

  build() {
    Column() {
      Text($r('app.string.title'))
        .fontSize(22)
        .fontWeight(FontWeight.Bold)
        .fontColor($r('app.color.title_text'))
        .margin({ top: 48 })

      Text($r('app.string.count_format', this.count))
        .fontSize(56)
        .fontColor($r('app.color.count_text'))
        .margin({ top: 32 })

      Button($r('app.string.add'), { type: ButtonType.Normal })
        .width(200)
        .height(48)
        .margin({ top: 40 })
        .backgroundColor($r('app.color.accent'))
        .fontColor($r('app.color.button_label'))
        .borderRadius(4)
        .onClick(() => {
          this.count += 1;
        })

      Button($r('app.string.reset'), { type: ButtonType.Normal })
        .width(200)
        .height(48)
        .margin({ top: 12 })
        .backgroundColor($r('app.color.button_secondary'))
        .fontColor($r('app.color.button_label'))
        .borderRadius(4)
        .enabled(this.count > 0)
        .onClick(() => {
          this.count = 0;
        })
    }
    .width('100%')
    .height('100%')
    .padding(24)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Start)
    .backgroundColor($r('app.color.screen_background'))
  }
}
"}

